DROP VIEW IF EXISTS replset.vw_bank_expenses_to_allocate CASCADE;  CREATE OR REPLACE VIEW replset.vw_bank_expenses_to_allocate AS  SELECT date_period,     account_name,     account_code,     organization_code,     organization_name,     shop_code,     shop_name,     cost_item_code,     cost_item_name,     amount,     amountvat,     amountwithvat    FROM vw_all_expenses_with_vat buhreg   WHERE ((organization_code = '000000001'::text) AND (cost_item_code = '000000023'::text))   GROUP BY date_period, account_name, account_code, organization_code, organization_name, shop_code, shop_name, cost_item_code, cost_item_name, amount, amountvat, amountwithvat;
